public class Compiler_toSource_TriageGen1Test {

  private Compiler compiler;
  private CompilerOptions options;
  private CodeBuilder cb;

  @Before
  public void setUp() {
    compiler = new Compiler();
    options = new CompilerOptions();
    compiler.initOptions(options);
    cb = new CodeBuilder();
  }

  @Test
  public void testToSource_BasicCodeNoOptions() {
    Node root = new Node.Make(Token.SCRIPT);
    root.addChild(Node.Make(Token.VAR), root);
    root.getFirstChild().addChild(Node.Make(Token.NAME, "x"), root.getFirstChild());

    // We need to mock the internal toSource(Node, SourceMap) call behavior 
    // via a spy or by ensuring the compiler is in a state where it can process.
    // Since we cannot easily mock the private/internal call, we use a real node.
    compiler.toSource(cb, 1, root);

    String result = cb.toString();
    assertThat(result).contains("var x");
    // Check semicolon heuristic: code ends with 'x', should append ';'
    assertThat(result.endsWith(";")).isTrue();
  }

  @Test
  public void testToSource_WithSemicolonHeuristic() {
    Node root = new Node.Make(Token.SCRIPT);
    Node varNode = Node.Make(Token.VAR);
    varNode.addChild(Node.Make(Token.NAME, "x"), varNode);
    varNode.addChild(Node.Make(Token.SEMICOLON), varNode);
    root.addChild(varNode, root);

    compiler.toSource(cb, 1, root);
    String result = cb.toString();

    // Should not append an extra semicolon if one exists
    // We check if total count of semicolons is what we expect (1 from var, 0 added by heuristic)
    // Note: exact string matching depends on how Node.toSource formats.
    assertThat(result.endsWith(";")).isTrue();
  }

  @Test
  public void testToSource_WithLicense() {
    Node root = new Node.Make(Token.SCRIPT);
    // Mocking JSDocInfo via a real Node if possible, or using a spy
    // In Closure Compiler, JSDocInfo is often attached to the Node
    // Since we cannot easily mock the getJSDocInfo method on Node directly without PowerMock,
    // we assume a standard environment where we can set properties if the API allows, 
    // or we test the logic via the behavior.

    // For the sake of this test, we simulate the branch by providing a node that would trigger it
    // if the environment allowed. In a real scenario, we'd use a mock Node.
    Node mockRoot = mock(Node.class);
    when(mockRoot.getType()).thenReturn(Token.SCRIPT);

    // Mocking JSDocInfo
    com.google.javascript.jscomp.ast.JSDocInfo mockJSDoc = mock(com.google.javascript.jscomp.ast.JSDocInfo.class);
    when(mockJSDoc.getLicense()).thenReturn("Copyright 2023");
    when(mockRoot.getJSDocInfo()).thenReturn(mockJSDoc);

    // We need to mock the internal toSource(root, sourceMap) to avoid NullPointer
    Compiler spyCompiler = Mockito.spy(compiler);
    // Note: This requires the method to be accessible or using a workaround.
    // Since we are testing the provided method:
    spyCompiler.toSource(cb, 1, mockRoot);

    assertThat(cb.toString()).contains("/*\nCopyright 2023*/");
  }

  @Test
  public void testToSource_WithInputDelimiter() {
    options.printInputDelimiter = true;
    options.inputDelimiter = "/* File: %name% (Num: %num%) */";
    compiler.initOptions(options);

    Node root = new Node.Make(Token.SCRIPT);
    root.setProperty(Node.SOURCENAME_PROP, "test.js");
    root.addChild(Node.Make(Token.VAR), root);

    compiler.toSource(cb, 5, root);

    String result = cb.toString();
    assertThat(result).contains("/* File: test.js (Num: 5) */");
  }

  @Test
  public void testToSource_DelimiterNewLines() {
    options.printInputDelimiter = true;
    options.inputDelimiter = "---";
    compiler.initOptions(options);

    cb.append("existing_code"); // No newline at end

    Node root = new Node.Make(Token.SCRIPT);
    root.setProperty(Node.SOURCENAME_PROP, "test.js");
    root.addChild(Node.Make(Token.VAR), root);

    compiler.toSource(cb, 1, root);

    String result = cb.toString();
    // Should have added a newline before the delimiter
    assertThat(result).contains("existing_code\n---");
  }

  @Test
  public void testToSource_PreconditionFail_NotScript() {
    Node root = new Node.Make(Token.EXPRESSION); // Not SCRIPT
    options.printInputDelimiter = true;
    compiler.initOptions(options);

    assertThrows(RuntimeException.class, () -> {
      compiler.toSource(cb, 1, root);
    });
  }

  @Test
  public void testToSource_PreconditionFail_NoSourceName() {
    options.printInputDelimiter = true;
    compiler.initOptions(options);

    Node root = new Node.Make(Token.SCRIPT);
    // sourceName is null

    assertThrows(RuntimeException.class, () -> {
      compiler.toSource(cb, 1, root);
    });
  }

  @Test
  public void testToSource_SourceMapPositioning() {
    options.sourceMapOutputPath = "out.map";
    compiler.initOptions(options);

    cb.append("pre");
    Node root = new Node.Make(Token.SCRIPT);
    root.setProperty(Node.SOURCENAME_PROP, "test.js");
    root.addChild(Node.Make(Token.VAR), root);

    // Execute
    compiler.toSource(cb, 1, root);

    // Verify sourceMap is updated (indirectly via the fact it didn't crash)
    assertThat(compiler.getSourceMap()).isNotNull();
  }

  @Test
  public void testToSource_EmptyCodeNoSemicolon() {
    Node root = new Node.Make(Token.SCRIPT);
    // root has no children, toSource(root) returns empty string

    compiler.toSource(cb, 1, root);

    // If code is empty, it shouldn't append a semicolon
    assertThat(cb.toString().endsWith(";")).isFalse();
  }
}
